const products=[
{id:'good-key',name:'按按小方',en:'THE GOOD KEY',type:'press',format:'打印成品',color:'#ddd1eb',art:'key',desc:'一枚方方的快乐，按一下，给思绪放个小假。',detail:'方形按键挂饰的造型探索，以圆润边缘和机械按压为设计方向。',mark:'01'},
{id:'cloud-key',name:'云朵按键',en:'SOFT LITTLE CLOUD',type:'press',format:'打印成品',color:'#f6dfab',art:'cloud',desc:'把一朵软乎乎的好心情，挂在身边。',detail:'以柔软轮廓为灵感的按压挂饰概念，将圆润外形与按键玩法结合。',mark:'02'},
{id:'spin-ring',name:'转转甜甜圈',en:'ROUND & ROUND',type:'spin',format:'打印成品',color:'#f1c6b5',art:'spin',desc:'手指转一圈，日常多一点轻松。',detail:'环形旋转小物的造型探索，围绕随手转动和便携携带展开。',mark:'03'},
{id:'good-file',name:'小方 · 设计文件',en:'MAKE YOUR OWN GOOD',type:'file',format:'数字文件',color:'#cfdfcd',art:'file',desc:'用自己的打印机，让一个好点子成形。',detail:'按按小方的数字设计文件概念，面向希望自行打印和组装的使用者。文件格式、配件及授权范围尚未公布。',mark:'04'}];
function art(p){if(p.art==='spin')return '<span class="spinner peach" aria-hidden="true"><span class="spinner-inner"><i></i><i></i><i></i></span></span>';if(p.art==='file')return '<span class="file-object" aria-hidden="true"><span>OGS<br>DESIGN FILE</span><b>＋</b><small>MAKE IT YOURS.</small></span>';return `<span class="toy ${p.art==='cloud'?'cloud':''}" aria-hidden="true"><span class="ring"></span><span class="toy-base"><span class="keycap"><i class="eye left"></i><i class="eye right"></i><i class="smile"></i><em>${p.art==='cloud'?'SOFT':'GOOD'}</em></span></span></span>`}
let cart={};try{const saved=JSON.parse(localStorage.getItem('ogs-cart-v1')||'{}');for(const p of products){const q=saved[p.id];if(Number.isInteger(q)&&q>0)cart[p.id]=Math.min(q,99)}}catch{}
let filter='all';const qs=s=>document.querySelector(s);const count=()=>Object.values(cart).reduce((a,b)=>a+b,0);
function renderProducts(){qs('#products').innerHTML=products.filter(p=>filter==='all'||(filter==='physical'?p.type!=='file':p.type===filter)).map(p=>`<article class="product-card"><button class="product-art" style="background:${p.color}" data-detail="${p.id}" aria-label="查看${p.name}详情">${art(p)}<span class="card-stamp">${p.format}</span><span class="art-index">OGS / ${p.mark}</span></button><div class="product-info"><div class="product-meta"><span>${p.en}</span><span>概念款</span></div><h3><button class="title-link" data-detail="${p.id}">${p.name}</button></h3><p>${p.desc}</p><div class="card-bottom"><span>售价未公布</span><button class="add" data-add="${p.id}" aria-label="将${p.name}加入体验购物车">＋</button></div></div></article>`).join('')}
function setFilter(value){filter=value;document.querySelectorAll('[data-filter]').forEach(b=>{const active=b.dataset.filter===value||(value==='physical'&&b.dataset.filter==='all');b.classList.toggle('active',active);b.setAttribute('aria-pressed',active)});renderProducts()}
function persist(){try{localStorage.setItem('ogs-cart-v1',JSON.stringify(cart))}catch{}renderCart()}
function renderCart(){qs('#cart-count').textContent=count();qs('#drawer-count').textContent=count();qs('#cart-items').innerHTML=count()?products.filter(p=>cart[p.id]).map(p=>`<article class="cart-row"><div class="cart-thumb" style="background:${p.color}" aria-hidden="true">${p.art==='file'?'▤':p.art==='spin'?'◎':'▣'}</div><div><h3>${p.name}</h3><p>${p.format} · 概念款 · 售价未公布</p><div class="qty"><button data-qty="${p.id}" data-change="-1" aria-label="减少${p.name}数量">−</button><span aria-label="数量">${cart[p.id]}</span><button data-qty="${p.id}" data-change="1" aria-label="增加${p.name}数量" ${cart[p.id]>=99?'disabled':''}>＋</button><button class="remove" data-remove="${p.id}">移除</button></div></div></article>`).join(''):'<div class="empty"><span>✳</span>购物车里，还差一点小快乐。</div>'}
let toastTimer;function toast(message){qs('#toast').textContent=message;qs('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>qs('#toast').classList.remove('show'),2500)}
function add(id){if(!products.some(p=>p.id===id))return;cart[id]=Math.min((cart[id]||0)+1,99);persist();toast('已加入体验购物车 · 当前不生成订单')}
function detail(id){const p=products.find(x=>x.id===id);if(!p)return;qs('#product-detail').innerHTML=`<div class="detail-grid"><div class="product-art" style="background:${p.color}">${art(p)}</div><div><span class="eyebrow">${p.en}</span><h2>${p.name}</h2><p>${p.detail}</p><span class="pill">${p.format}</span><p class="detail-note">概念造型示意，非实际商品照片。暂未开售；价格、规格及交付内容以正式发布为准。</p><button class="button yellow" data-add="${p.id}">加入体验购物车</button></div></div>`;qs('#product-dialog').showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.filter)setFilter(b.dataset.filter);if(b.dataset.select){setFilter(b.dataset.select==='all'?'physical':b.dataset.select);qs('#shop').scrollIntoView({behavior:'smooth'})}if(b.dataset.detail)detail(b.dataset.detail);if(b.dataset.add)add(b.dataset.add);if(b.dataset.qty){const id=b.dataset.qty;cart[id]=Math.max(0,Math.min(99,(cart[id]||0)+Number(b.dataset.change)));if(!cart[id])delete cart[id];persist()}if(b.dataset.remove){delete cart[b.dataset.remove];persist()}if(b.hasAttribute('data-close'))b.closest('dialog').close()});
qs('#open-cart').onclick=()=>{renderCart();qs('#cart-dialog').showModal()};qs('#keep-shopping').onclick=()=>{qs('#cart-dialog').close();qs('#shop').scrollIntoView({behavior:'smooth'})};qs('#open-info').onclick=()=>qs('#info-dialog').showModal();
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
let presses=0,pressTimer;qs('#press-toy').onclick=()=>{presses++;qs('#press-toy').classList.add('pressed');clearTimeout(pressTimer);pressTimer=setTimeout(()=>qs('#press-toy').classList.remove('pressed'),180);qs('#press-label').textContent=['好心情 +1','再按一下？','小快乐，收到！'][presses%3]};let spin=0;qs('#spin-toy').onclick=()=>{spin+=240;qs('#spin-toy .spinner-inner').style.transform=`rotate(${spin}deg)`};qs('#year').textContent=new Date().getFullYear();renderProducts();renderCart();
